// THE INTERFACE: legacy abstract method + NEW default methods (backward-compatible!)
package com.bank.evolution.service;

import com.bank.evolution.dto.AccountSummary;
import com.bank.evolution.model.Account;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.text.NumberFormat;
import java.util.Locale;

public interface AccountService {

    // ═══ ORIGINAL ABSTRACT METHOD (exists since day 1) ═══
    Account getAccount(String accountId);

    // ═══ DEFAULT METHOD 1: formatted balance — added in Java 8 style ═══
    // All 12 implementing classes get this FREE — no override needed!
    default String getFormattedBalance(String accountId) {
        Account account = getAccount(accountId);  // calls the abstract method!
        NumberFormat fmt = NumberFormat.getCurrencyInstance(new Locale("en", "IN"));
        return fmt.format(account.getBalance());
    }

    // ═══ DEFAULT METHOD 2: balance alert — low balance warning ═══
    default String getBalanceAlert(String accountId) {
        Account account = getAccount(accountId);
        if (account.getBalance().compareTo(account.getMinBalance()) < 0) {
            return "(Caution) LOW BALANCE: Rs." + account.getBalance().setScale(2, RoundingMode.HALF_UP)
                + " is below minimum Rs." + account.getMinBalance().setScale(2, RoundingMode.HALF_UP);
        }
        return "(Recommended) Balance healthy";
    }

    // ═══ DEFAULT METHOD 3: summary — combines everything ═══
    default AccountSummary getSummary(String accountId) {
        Account account = getAccount(accountId);
        return new AccountSummary(
            accountId,
            account.getHolderName(),
            getFormattedBalance(accountId),   // calls another default method!
            getBalanceAlert(accountId),       // calls another default method!
            getClass().getSimpleName()        // shows which implementation is running
        );
    }

    // ═══ STATIC METHOD: utility — NOT inherited by implementing classes ═══
    static BigDecimal calculateInterest(BigDecimal balance, BigDecimal rate, int days) {
        return balance.multiply(rate)
            .multiply(BigDecimal.valueOf(days))
            .divide(BigDecimal.valueOf(365), 2, RoundingMode.HALF_UP);
    }

    // ═══ STATIC FACTORY: creates a quick read-only service ═══
    static AccountService readOnly(Account account) {
        return accountId -> account;  // lambda! returns same account regardless
    }
}
```

