// DOES NOT override default methods — gets them FREE
package com.bank.evolution.service;

import com.bank.evolution.model.Account;
import com.bank.evolution.repository.AccountRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service("savingsService")
@RequiredArgsConstructor
@Slf4j
public class SavingsAccountService implements AccountService {

    private final AccountRepository accountRepo;

    // Only implements the ONE abstract method — gets 3 default methods FREE!
    @Override
    @Transactional(readOnly = true)
    public Account getAccount(String accountId) {
        log.info("[SAVINGS] Loading account: {}", accountId);
        return accountRepo.findById(accountId)
            .orElseThrow(() -> new IllegalArgumentException("Account not found: " + accountId));
    }

    // getFormattedBalance() → INHERITED from default
    // getBalanceAlert() → INHERITED from default
    // getSummary() → INHERITED from default
}
