package com.bank.evolution.controller;

import com.bank.evolution.dto.AccountSummary;
import com.bank.evolution.model.Account;
import com.bank.evolution.service.AccountService;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.web.bind.annotation.*;
import java.math.BigDecimal;
import java.util.Map;

@RestController
@RequestMapping("/api/v1/accounts")
@Slf4j
public class AccountController {

    private final AccountService savingsService;
    private final AccountService currentService;

    public AccountController(
        @Qualifier("savingsService") AccountService savingsService,
        @Qualifier("currentService") AccountService currentService
    ) {
        this.savingsService = savingsService;
        this.currentService = currentService;
    }

    @GetMapping("/savings/{accountId}/summary")
    public AccountSummary savingsSummary(@PathVariable String accountId) {
        return savingsService.getSummary(accountId);
        // Uses DEFAULT getFormattedBalance() → currency format
    }

    @GetMapping("/current/{accountId}/summary")
    public AccountSummary currentSummary(@PathVariable String accountId) {
        return currentService.getSummary(accountId);
        // Uses OVERRIDDEN getFormattedBalance() → "Business Balance: ₹..."
    }

    @GetMapping("/interest")
    public Map<String, Object> calculateInterest(
        @RequestParam BigDecimal balance,
        @RequestParam BigDecimal rate,
        @RequestParam int days
    ) {
        // STATIC method — called via InterfaceName.method()
        BigDecimal interest = AccountService.calculateInterest(balance, rate, days);
        return Map.of("balance", balance, "rate", rate, "days", days, "interest", interest);
    }
}
