package com.bank.evolution.service;

import com.bank.evolution.dto.AccountSummary;
import com.bank.evolution.model.Account;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

class AccountServiceDefaultTest {

    @Test
    void shouldInheritDefaultFormattedBalance() {
        Account account = mock(Account.class);
        when(account.getBalance()).thenReturn(new BigDecimal("125000.50"));

        // Anonymous impl — only implements getAccount(), gets defaults FREE
        AccountService service = accountId -> account;

        String formatted = service.getFormattedBalance("SAV2001");
        assertThat(formatted).contains("1,25,000.50"); // Indian format
    }

    @Test
    void shouldDetectLowBalance() {
        Account lowBalAccount = mock(Account.class);
        when(lowBalAccount.getBalance()).thenReturn(new BigDecimal("3200"));
        when(lowBalAccount.getMinBalance()).thenReturn(new BigDecimal("5000"));

        AccountService service = accountId -> lowBalAccount;

        String alert = service.getBalanceAlert("SAV2002");
        assertThat(alert).contains("LOW BALANCE");
    }

    @Test
    void shouldReturnHealthyForGoodBalance() {
        Account healthyAccount = mock(Account.class);
        when(healthyAccount.getBalance()).thenReturn(new BigDecimal("125000"));
        when(healthyAccount.getMinBalance()).thenReturn(new BigDecimal("5000"));

        AccountService service = accountId -> healthyAccount;

        String alert = service.getBalanceAlert("SAV2001");
        assertThat(alert).contains("healthy");
    }

    @Test
    void staticMethodCalculatesInterest() {
        // Static method — called via InterfaceName.method()
        BigDecimal interest = AccountService.calculateInterest(
            new BigDecimal("100000"), new BigDecimal("0.06"), 30);
        assertThat(interest).isEqualByComparingTo("493.15"); // 100000 × 0.06 × 30/365
    }

    @Test
    void staticFactoryCreatesReadOnlyService() {
        Account account = mock(Account.class);
        when(account.getBalance()).thenReturn(new BigDecimal("50000"));

        AccountService readOnly = AccountService.readOnly(account);
        assertThat(readOnly.getAccount("anything")).isSameAs(account);
    }

    @Test
    void defaultSummaryUsesOtherDefaults() {
        Account account = mock(Account.class);
        when(account.getAccountId()).thenReturn("SAV2001");
        when(account.getHolderName()).thenReturn("Rajesh Kumar");
        when(account.getBalance()).thenReturn(new BigDecimal("125000.50"));
        when(account.getMinBalance()).thenReturn(new BigDecimal("5000"));

        AccountService service = accountId -> account;

        AccountSummary summary = service.getSummary("SAV2001");
        assertThat(summary.holderName()).isEqualTo("Rajesh Kumar");
        assertThat(summary.formattedBalance()).contains("1,25,000.50");
        assertThat(summary.alertMessage()).contains("healthy");
    }
}
